DROP TABLE IF EXISTS `basic_work_calendar_day`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `basic_work_calendar_day` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户 ID，固定为 0',
  `calendar_date` date NOT NULL COMMENT '日期',
  `year_value` int NOT NULL COMMENT '年',
  `month_value` int NOT NULL COMMENT '月',
  `day_value` int NOT NULL COMMENT '日',
  `date_type` tinyint NOT NULL DEFAULT '1' COMMENT '日期类型：1 工作日，2 公休日，3 法定节假日，4 调休工作日，5 自定义假期，6 活动日',
  `holiday_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '节假日名称',
  `custom_week` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '自定义周别',
  `public_week` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '公共周别',
  `is_holiday_synced` tinyint NOT NULL DEFAULT '0' COMMENT '是否同步法定节假日',
  `holiday_source_year` int DEFAULT NULL COMMENT '节假日来源年份',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0 未删除，1 已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_work_calendar_day_date` (`calendar_date`,`deleted`) USING BTREE,
  KEY `idx_work_calendar_day_month` (`year_value`,`month_value`,`date_type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1096 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='工作日历日期主数据';
/*!40101 SET character_set_client = @saved_cs_client */;

