  `expire_date` date NOT NULL DEFAULT '9999-12-31' COMMENT '失效日期',
  `approve_status` tinyint NOT NULL DEFAULT '0' COMMENT '审批状态：0-待审批 1-已生效 2-已驳回 3-审批中',
