  KEY `idx_mdm_rate_status` (`tenant_id`,`approve_status`,`deleted`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='汇率明细表';
