--
-- Table structure for table `sys_file_storage`
--

DROP TABLE IF EXISTS `sys_file_storage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_file_storage` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `storage_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '存储类型(LOCAL/OSS/MINIO)',
  `storage_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '存储名称',
  `config_json` json DEFAULT NULL COMMENT '配置(JSON)',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(1启用,0禁用)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint DEFAULT '0' COMMENT '逻辑删除',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_tenant_type` (`tenant_id`,`storage_type`) USING BTREE,
  KEY `idx_tenant_default` (`tenant_id`,`is_default`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='文件存储配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_file_storage`
--

LOCK TABLES `sys_file_storage` WRITE;
/*!40000 ALTER TABLE `sys_file_storage` DISABLE KEYS */;
/*!40000 ALTER TABLE `sys_file_storage` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `sys_help_resource`
--

DROP TABLE IF EXISTS `sys_help_resource`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_help_resource` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户 ID',
  `title` varchar(200) NOT NULL COMMENT '资源标题',
  `doc_type` varchar(20) NOT NULL COMMENT '文档类型：MANUAL=手册，VIDEO=视频',
  `scope_type` varchar(20) NOT NULL COMMENT '范围：GLOBAL=全局，MENU=菜单覆盖',
  `source_type` varchar(20) NOT NULL DEFAULT 'FILE' COMMENT '来源：FILE=上传文件，EXTERNAL_URL=外链',
  `menu_id` bigint DEFAULT NULL COMMENT '绑定菜单 ID，GLOBAL 时为空',
  `menu_path` varchar(255) DEFAULT NULL COMMENT '工作区全路径，便于按路由匹配',
  `file_name` varchar(255) DEFAULT NULL COMMENT '原始文件名',
  `file_url` varchar(500) DEFAULT NULL COMMENT '文件访问地址',
  `file_ext` varchar(20) DEFAULT NULL COMMENT '文件扩展名，不含点',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `content_type` varchar(100) DEFAULT NULL COMMENT '文件 MIME 类型',
  `external_url` varchar(1000) DEFAULT NULL COMMENT '外链地址',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0=禁用，1=启用',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号，越小越靠前',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0=未删除，1=已删除',
  PRIMARY KEY (`id`),
  KEY `idx_help_type_scope_status` (`doc_type`,`scope_type`,`status`,`deleted`),
  KEY `idx_help_menu_path` (`menu_path`,`doc_type`,`status`),
  KEY `idx_help_tenant_status` (`tenant_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='帮助资源（手册/视频）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_help_resource`
--

LOCK TABLES `sys_help_resource` WRITE;
/*!40000 ALTER TABLE `sys_help_resource` DISABLE KEYS */;
/*!40000 ALTER TABLE `sys_help_resource` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `sys_homepage_component_category`
--

DROP TABLE IF EXISTS `sys_homepage_component_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_homepage_component_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类编码',
  `category_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类名称',
  `module_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模块编码',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
