  `receiver_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '接收人ID列表(JSON数组格式,如[1,2,3])',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
